CREATE TABLE audit_runs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,case_id TEXT NOT NULL REFERENCES audit_cases(id) ON DELETE CASCADE,case_revision INTEGER NOT NULL,payload TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX audit_runs_case ON audit_runs(tenant_id,case_id,created_at);
CREATE TABLE audit_corrections(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,case_id TEXT NOT NULL REFERENCES audit_cases(id) ON DELETE CASCADE,case_revision INTEGER NOT NULL,run_id TEXT REFERENCES audit_runs(id) ON DELETE SET NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',revision INTEGER NOT NULL DEFAULT 1,synthetic INTEGER NOT NULL,created_by TEXT NOT NULL,modified_by TEXT NOT NULL,approved_by TEXT,content_hash TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX audit_corrections_tenant ON audit_corrections(tenant_id,id);
CREATE TABLE correction_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,correction_id TEXT NOT NULL REFERENCES audit_corrections(id) ON DELETE CASCADE,revision INTEGER NOT NULL,status TEXT NOT NULL,actor TEXT NOT NULL,content_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER correction_journal_insert AFTER INSERT ON audit_corrections BEGIN INSERT INTO correction_events VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.id,NEW.revision,NEW.status,NEW.modified_by,NEW.content_hash,unixepoch()); END;
CREATE TRIGGER correction_journal_update AFTER UPDATE ON audit_corrections BEGIN INSERT INTO correction_events VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.id,NEW.revision,NEW.status,NEW.modified_by,NEW.content_hash,unixepoch()); END;
CREATE TRIGGER audit_runs_quota_insert BEFORE INSERT ON audit_runs BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER audit_runs_quota_update BEFORE UPDATE OF payload ON audit_runs WHEN length(CAST(NEW.payload AS BLOB))>length(CAST(OLD.payload AS BLOB)) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER audit_runs_usage_insert AFTER INSERT ON audit_runs BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER audit_runs_usage_update AFTER UPDATE OF payload ON audit_runs BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER audit_runs_usage_delete AFTER DELETE ON audit_runs BEGIN UPDATE tenants SET used_bytes=used_bytes-length(CAST(OLD.payload AS BLOB)) WHERE id=OLD.tenant_id; END;
CREATE TRIGGER audit_corrections_quota_insert BEFORE INSERT ON audit_corrections BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER audit_corrections_quota_update BEFORE UPDATE OF payload ON audit_corrections WHEN length(CAST(NEW.payload AS BLOB))>length(CAST(OLD.payload AS BLOB)) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER audit_corrections_usage_insert AFTER INSERT ON audit_corrections BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER audit_corrections_usage_update AFTER UPDATE OF payload ON audit_corrections BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER audit_corrections_usage_delete AFTER DELETE ON audit_corrections BEGIN UPDATE tenants SET used_bytes=used_bytes-length(CAST(OLD.payload AS BLOB)) WHERE id=OLD.tenant_id; END;
